/**
 * 目录协议路径解析（v2.2 定稿 §3 布局）。
 *
 * teamHome 即实例根：ADR 0005（#13 冻结口径）下由宿主绑定层解析为
 * `<DSH_HOME>/xiaozhuge/sessions/<主会话id>`，本库不关心其绝对形态，
 * 只按协议拼出各文件/目录的落点。
 */
import { join } from "node:path";

export interface RoomLayout {
  dir: string;
  /** append-only 事件流（仅运行时单写者）。 */
  eventsFile: string;
  /** 黑板 per-role 分片目录。 */
  stateDir: string;
  /** 简报目录。 */
  briefDir: string;
}

export interface Layout {
  teamHome: string;
  teamYaml: string;
  agentsJson: string;
  /** CAS 锁资源基路径（不含 .lock 后缀）；锁形态为 room.lock 目录（proper-lockfile）。 */
  roomLock: string;
  ledgerTasksDir: string;
  roomsDir: string;
  mailboxDir: string;
  gatesDir: string;
  archiveDir: string;
}

/** 解析实例根下的顶层协议路径。teamHome 即实例根，不再追加 <instance-id> 层。 */
export function layout(teamHome: string): Layout {
  return {
    teamHome,
    teamYaml: join(teamHome, "team.yaml"),
    agentsJson: join(teamHome, "agents.json"),
    roomLock: join(teamHome, "room"),
    ledgerTasksDir: join(teamHome, "ledger", "tasks"),
    roomsDir: join(teamHome, "rooms"),
    mailboxDir: join(teamHome, "mailbox"),
    gatesDir: join(teamHome, "gates"),
    archiveDir: join(teamHome, "archive"),
  };
}

/** 解析单个房间的布局。 */
export function roomLayout(teamHome: string, room: string): RoomLayout {
  const dir = join(layout(teamHome).roomsDir, room);
  return {
    dir,
    eventsFile: join(dir, "events.jsonl"),
    stateDir: join(dir, "state"),
    briefDir: join(dir, "brief"),
  };
}

/** 信箱成员目录。 */
export function memberMailboxDir(teamHome: string, member: string): string {
  return join(layout(teamHome).mailboxDir, member);
}

src/runtime/recovery.ts.source:
/**
 * 崩溃恢复原语（v2.2 定稿 §5 幂等与恢复表）：
 * - 信箱 .delivering-* TTL 收割（omo 模式，P2b 三段式的恢复半边）；
 * - 黑板 running 哨兵整分片作废重做；
 * - 原子写临时残片清扫。
 * 收割/作废结果以清单返回，审计事件由调用方追加到事件流。
 */
import { existsSync } from "node:fs";
import { link, readdir, rm, stat } from "node:fs/promises";
import { join } from "node:path";
import { TMP_PREFIX, readJson } from "./fs-utils.js";
import type { MemberRecord } from "./types.js";

/** 默认投递中 TTL：10 分钟（巡场轮次为分钟级节奏，够宽也够收）。 */
export const DEFAULT_DELIVERING_TTL_MS = 10 * 60_000;

export interface DeliveryRecovery {
  member: string;
  uuid: string;
  /** requeued = 回待读位；dropped = 待读位已存在（processed 防线命中），残片丢弃。 */
  action: "requeued" | "dropped";
}

/**
 * 收割超时的 .delivering-<uuid>.json 残片。
 * 直接 rename 回待读位；目标已存在（EEXIST）即丢弃残片——不做 stat-then-rename
 * （TOCTOU）。已确认过的 uuid 在 processed 位时其待读位不应存在；若存在说明
 * 确认前崩溃，回待读位是正确重投。
 */
export async function recoverDeliveries(
  mailboxDir: string,
  ttlMs = DEFAULT_DELIVERING_TTL_MS,
  now = Date.now(),
): Promise<DeliveryRecovery[]> {
  if (!existsSync(mailboxDir)) return [];
  const result: DeliveryRecovery[] = [];
  for (const member of await readdir(mailboxDir)) {
    const memberDir = join(mailboxDir, member);
    if (!existsSync(memberDir)) continue;
    for (const entry of await readdir(memberDir)) {
      if (!entry.startsWith(".delivering-") || !entry.endsWith(".json")) continue;
      const uuid = entry.slice(".delivering-".length, -".json".length);
      const full = join(memberDir, entry);
      const { mtimeMs } = await stat(full);
      if (now - mtimeMs < ttlMs) continue;
      const target = join(memberDir, `${uuid}.json`);
      // link = 原子 create-if-not-exists：待读位已被占（processed 防线命中）
      // 时 EEXIST，残片丢弃；绝不用 rename（会静默覆盖待读位）。
      try {
        await link(full, target);
        await rm(full);
        result.push({ member, uuid, action: "requeued" });
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "EEXIST") {
          await rm(full);
          result.push({ member, uuid, action: "dropped" });
        } else {
          throw error;
        }
      }
    }
  }
  return result;
}

export interface SentinelRecovery {
  role: string;
  action: "discarded";
}

/**
 * 黑板 running 哨兵处理：state/<role>.json 含 `"status":"running"` 的分片
 * 整体作废重做（unlink 整文件——半新半旧的脏黑板不可复用）。
 */
export async function discardRunningSentinels(stateDir: string): Promise<SentinelRecovery[]> {
  if (!existsSync(stateDir)) return [];
  const result: SentinelRecovery[] = [];
  for (const entry of await readdir(stateDir)) {
    if (!entry.endsWith(".json")) continue;
    const full = join(stateDir, entry);
    const shard = await readJson<{ status?: string }>(full);
    if (shard?.status !== "running") continue;
    await rm(full);
    result.push({ role: entry.replace(/\.json$/, ""), action: "discarded" });
  }
  return result;
}

src/runtime/registry.ts.source:
/**
 * agents.json 成员注册表读写：父死子活对账的数据源（v2.2 定稿 §4）。
 * 单文件原子写；调用方负责持 room.lock 期间再写（本层不做跨进程仲裁）。
 */
import { join } from "node:path";
import type { MemberRecord, TeamRegistry } from "./types.js";
import { readJson, writeJsonAtomic } from "./fs-utils.js";

export class Registry {
  private readonly file: string;

  constructor(teamHome: string) {
    this.file = join(teamHome, "agents.json");
  }

  /** 读注册表；不存在视为空团队。 */
  async read(): Promise<TeamRegistry> {
    const data = await readJson<TeamRegistry>(this.file);
    return data ?? { members: {} };
  }

  /** 整体原子写。 */
  async write(registry: TeamRegistry): Promise<void> {
    await writeJsonAtomic(this.file, registry);
  }

  /** 登记或更新成员。 */
  async upsertMember(record: MemberRecord): Promise<void> {
    const reg = await this.read();
    reg.members[record.member] = record;
    await this.write(reg);
  }

  /** 读单个成员。 */
  async getMember(member: string): Promise<MemberRecord | undefined> {
    const reg = await this.read();
    return reg.members[member];
  }

  /** 更新成员状态与 lastSeen；成员不存在即拒。 */
  async setStatus(member: string, status: MemberRecord["status"]): Promise<void> {
    const reg = await this.read();
    const existing = reg.members[member];
    if (existing === undefined) {
      throw new Error(`member ${member} is not registered`);
    }
    existing.status = status;
    existing.lastSeen = Date.now();
    await this.write(reg);
  }

  /** 存活成员清单（status !== dead），供 reattach 对账。 */
  async liveMembers(): Promise<MemberRecord[]> {
    const reg = await this.read();
    return Object.values(reg.members).filter((m) => m.status !== "dead");
  }
}

src/runtime/template-loader.ts.source:
/**
 * 模板加载原语（P6a，ADR 0005/#13 三级来源口径）。
 *
 * 解析决策（#29 第 B 项）：模板内容为完整 YAML 1.2，由成熟解析器
 * `yaml`（eemeli，零传递依赖）读取——注释/块标量/锚点全量可用；
 * 此前的 JSON 兼容子集（issue #10 MVP 留痕）已被该 approved 决策取代。
 *
 * 来源三级：builtin（包内只读）/ user / project——同名不跨级覆盖，
 * 加载时标记来源即可区分（#13 冻结口径）。
 */
import { existsSync } from "node:fs";
import { readFile, readdir } from "node:fs/promises";
import { createHash } from "node:crypto";
import { join } from "node:path";
import { parse as parseYaml } from "yaml";
import type { TemplateSource } from "./types.js";
import { validateTeamTemplate, validateRoleSet } from "./template.js";

/** 模板场景目录内的固定文件名（v2.2 定稿 §7.1）。 */
export const TEAM_FILE = "team.yaml";
export const ROLES_DIR = "roles";
export const PROMPTS_DIR = "prompts";

export interface LoadedTemplate {
  /** team.yaml 解析结果（已通过校验）。 */
  template: Record<string, unknown> & {
    name: string;
    version: number;
    source?: TemplateSource;
  };
  /** role id -> Role Spec 对象（已通过集合校验）。 */
  roles: Record<string, Record<string, unknown>>;
  /** role/tier id -> prompt 文本（相对路径 -> 内联文本）。 */
  prompts: Record<string, string>;
  /** 来源标记。 */
  source: TemplateSource;
  /** 模板内容摘要（sha256，前 16 位）。 */
  digest: string;
}

/**
 * 从场景目录加载并校验模板。
 * @throws Error 目录缺失 / YAML 解析失败 / 校验不通过。
 */
export async function loadTemplate(
  scenarioDir: string,
  source: TemplateSource,
): Promise<LoadedTemplate> {
  const teamPath = join(scenarioDir, TEAM_FILE);
  if (!existsSync(teamPath)) {
    throw new Error(`template missing ${TEAM_FILE} in ${scenarioDir}`);
  }
  const teamRaw = await readFile(teamPath, "utf8");
  let template: Record<string, unknown> & { name: string; version: number; source?: TemplateSource };
  try {
    const parsed = parseYaml(teamRaw) as unknown;
    if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
      throw new Error("document must be a mapping");
    }
    template = parsed as typeof template;
  } catch (error) {
    throw new Error(`template ${teamPath} is not valid YAML: ${(error as Error).message}`);
  }

  // 强制注入来源标记（覆盖模板自带值——来源由加载位置决定，不由文件内容决定）。
  template.source = source;

  const rolesDir = join(scenarioDir, ROLES_DIR);
  const specs: Array<Record<string, unknown>> = [];
  const roles: Record<string, Record<string, unknown>> = {};
  if (existsSync(rolesDir)) {
    for (const entry of (await readFile2(rolesDir)).sort()) {
      if (!entry.endsWith(".role.yaml")) continue;
      const spec = parseYaml(await readFile(join(rolesDir, entry), "utf8")) as Record<string, unknown>;
      specs.push(spec);
      roles[String(spec.id)] = spec;
    }
  }

  // 校验：模板 + 角色集合（一次收集全部错误后统一抛出）。
  const tplResult = validateTeamTemplate(template);
  const setResult = validateRoleSet(specs);
  const allErrors = [
    ...tplResult.errors.map((e) => ({ ...e, path: `team.${e.path}` })),
    ...setResult.errors.map((e) => ({ ...e, path: `roles.${e.path}` })),
  ];
  if (allErrors.length > 0) {
    throw new Error(
      `template validation failed:\n${allErrors.map((e) => `- [${e.code}] ${e.path}: ${e.message}`).join("\n")}`,
    );
  }

  // prompt 内联：读 prompts/ 下被引用的文本（缺失即抛——实例化完整性硬约束）。
  const prompts: Record<string, string> = {};
  const referenced = new Set<string>();
  for (const tier of (template.tiers as Array<{ prompt?: string }>) ?? []) {
    if (typeof tier.prompt === "string") referenced.add(tier.prompt);
  }
  for (const spec of specs) {
    const p = (spec as { prompt?: unknown }).prompt;
    if (typeof p === "string") referenced.add(p);
  }
  for (const rel of referenced) {
    const promptPath = join(scenarioDir, rel);
    if (!existsSync(promptPath)) {
      throw new Error(`referenced prompt missing: ${rel}`);
    }
    prompts[rel] = await readFile(promptPath, "utf8");
  }

  return {
    template,
    roles,
    prompts,
    source,
    digest: createHash("sha256").update(JSON.stringify({ template, roles })).digest("hex").slice(0, 16),
  };
}

async function readFile2(dir: string): Promise<string[]> {
  return readdir(dir);
}

/** 实例化快照：模板 + 角色 + 来源标记 + digest（写入 TEAM_HOME/team.yaml 的对象）。 */
export function instantiateSnapshot(loaded: LoadedTemplate): Record<string, unknown> {
  return {
    name: loaded.template.name,
    version: loaded.template.version,
    source: loaded.source,
    digest: loaded.digest,
    tiers: loaded.template.tiers,
    roles: Object.values(loaded.roles).map((r) => ({
      id: r.id,
      prompt_inlined: loaded.prompts[String(r.prompt)] ?? null,
      briefing: r.briefing ?? null,
      dod: r.dod ?? [],
      max_hops: r.max_hops ?? 3,
      as_judge: r.as_judge === true,
    })),
    instantiated_at: Date.now(),
  };
}

/** 便捷：包内置只读模板目录（builtin 来源）。 */
export function builtinScenarioDir(packageRoot: string): string {
  return join(packageRoot, "templates", "oss-maintenance");
}

