    const readBack = await ledger.get(task.id);
    expect(readBack).toEqual({
      id: expect.stringMatching(/^task-[0-9a-f-]{36}$/),
      title: "实现 X",
      status: "queued",
      room: "root",
      assignee: "coder",
      touched: ["src/a.ts"],
      mutexGroups: ["g-core"],
      rounds: 0,
      maxRounds: 4,
