/**
 * 校验器穷举负矩阵：对 validateRoleSpec / validateTeamTemplate 的每条规则
 * 逐一变异输入并断言完整错误签名（code+path+message），保证 Stryker 对
 * 条件分支与消息文本的突变全部被杀伤。
 */
import { describe, expect, it } from "vitest";
import { validateRoleSpec, validateTeamTemplate } from "../../src/index.js";

const baseSpec = { id: "coder", prompt: "./p.md" };

function codes(result: { errors: Array<{ code: string }> }): string[] {
  return result.errors.map((e) => e.code);
}

describe("validateRoleSpec 穷举负矩阵", () => {
  const cases: Array<[string, unknown, string, string, string]> = [
    // [描述, 输入, code, path, message]
    ["非对象", "nope", "role-not-object", "", "role spec must be an object"],
    ["id 缺失", { prompt: "./p.md" }, "role-id-required", "id", "role id is required"],
    ["prompt 缺失", { id: "x" }, "role-prompt-required", "prompt", "prompt reference is required"],
    [
      "briefing 非对象",
      { ...baseSpec, briefing: 3 },
      "briefing-not-object",
      "briefing",
      "briefing must be an object",
    ],
    [
      "format 非法",
      { ...baseSpec, briefing: { format: "yaml" } },
      "briefing-format-invalid",
      "briefing.format",
      "format must be structured or freeform",
    ],
    [
      "sections_required 非数组",
      { ...baseSpec, briefing: { format: "structured", sections_required: "acceptance" } },
      "sections-not-array",
      "briefing.sections_required",
      "must be an array",
    ],
    [
      "sections_required 未知小节",
      { ...baseSpec, briefing: { format: "structured", sections_required: ["poetry"] } },
      "section-unknown",
      "briefing.sections_required",
      "unknown section: poetry",
    ],
    [
      "dod 非数组",
      { ...baseSpec, dod: "build 绿" },
      "dod-not-array",
      "dod",
      "dod must be an array of strings",
    ],
    [
      "dod 与 acceptance 双缺",
      { ...baseSpec },
      "dod-or-acceptance-required",
      "dod",
      "non-empty dod or briefing.sections_required containing acceptance is required",
    ],
    [
      "dod 全空串也算缺",
      { ...baseSpec, dod: ["", ""] },
      "dod-or-acceptance-required",
      "dod",
      "non-empty dod or briefing.sections_required containing acceptance is required",
    ],
    [
      "as_judge 非布尔",
      { ...baseSpec, as_judge: "yes", dod: ["d"] },
      "as-judge-not-bool",
      "as_judge",
      "as_judge must be a boolean",
    ],
    [
      "max_hops 为零",
      { ...baseSpec, max_hops: 0 },
      "max-hops-invalid",
      "max_hops",
      "max_hops must be a positive integer",
    ],
    [
      "max_hops 为负数",
      { ...baseSpec, max_hops: -2 },
      "max-hops-invalid",
      "max_hops",
      "max_hops must be a positive integer",
    ],
    [
      "max_hops 为非整数",
      { ...baseSpec, max_hops: 1.5 },
      "max-hops-invalid",
      "max_hops",
      "max_hops must be a positive integer",
    ],
    [
      "max_hops 为字符串",
      { ...baseSpec, max_hops: "3" },
      "max-hops-invalid",
      "max_hops",
      "max_hops must be a positive integer",
    ],
  ];

  for (const [desc, input, code, path, message] of cases) {
    it(`负例：${desc}`, () => {
      const result = validateRoleSpec(input);
      expect(result.ok).toBe(false);
      expect(result.errors).toContainEqual({ code, path, message });
    });
  }
});

describe("validateTeamTemplate 穷举负矩阵", () => {
  const validBase = {
    name: "n",
    version: 2,
    tiers: [
      { id: "master", prompt: "./m.md" },
      { id: "worker", prompt: "./w.md" },
    ],
    roles: [{ id: "qa", ref: "qa" }],
  };

  const cases: Array<[string, Record<string, unknown>, string]> = [
    [
      "模板非对象",
      "nope",
      "template-not-object",
    ],
    ["name 空", { ...validBase, name: "" }, "name-required"],
    ["version 非整数", { ...validBase, version: 1.5 }, "version-invalid"],
    ["tiers 缺失", { ...validBase, tiers: undefined }, "tiers-required"],
    [
      "tier 缺 id",
      {
        ...validBase,
        tiers: [
          { prompt: "./a.md" },
          { id: "b", prompt: "./b.md" },
        ],
      },
      "tier-id-required",
    ],
    [
      "tier 缺 prompt",
      {
        ...validBase,
        tiers: [
          { id: "a", prompt: "" },
          { id: "b", prompt: "./b.md" },
        ],
      },
      "tier-prompt-required",
    ],
    [
      "roles 元素无引用无 id",
      { ...validBase, roles: [{ title: "x" }] },
      "role-ref-required",
    ],
    [
      "roles 引用重复",
      { ...validBase, roles: [{ ref: "qa" }, "qa"] },
      "role-duplicate",
    ],
    ["comm_mode 非法", { ...validBase, comm_mode: "hybrid" }, "comm-mode-invalid"],
    [
      "explicit 无白名单",
      { ...validBase, comm_mode: "explicit" },
      "explicit-comm-required",
    ],
    [
      "comm 边缺 to",
      { ...validBase, comm_mode: "explicit", comm: [{ from: "master", to: "" }] },
      "comm-edge-invalid",
    ],
    [
      "archives 非数组",
      { ...validBase, archives: "nope" },
      "archives-not-array",
    ],
    [
      "archive 元素缺 id",
      { ...validBase, archives: [{ type: "url", url: "https://x" }] },
      "archive-id-required",
    ],
    [
      "file 型缺 target",
      { ...validBase, archives: [{ id: "f", type: "file" }] },
      "archive-target-required",
    ],
    [
      "url 型缺 url",
      { ...validBase, archives: [{ id: "u", type: "url" }] },
      "archive-url-required",
    ],
    [
      "file target 绝对路径越界",
      { ...validBase, archives: [{ id: "f", type: "file", target: "/etc/passwd" }] },
      "archive-target-escapes",
    ],
    [
      "gates 非数组",
      { ...validBase, gates: {} },
      "gates-not-array",
    ],
    [
      "gate 缺 id",
      { ...validBase, gates: [{ at: "master" }] },
      "gate-id-required",
    ],
    [
      "gate on 格式非法",
      {
        ...validBase,
        gates: [{ id: "g1", at: "master", on: "random-text" }],
      },
      "gate-on-invalid",
    ],
    [
      "resources 非对象",
      { ...validBase, resources: [1] },
      "resources-not-object",
    ],
    [
      "stages_ext 非数组",
      { ...validBase, stages_ext: "running" },
      "stages-ext-not-array",
    ],
  ];

  for (const [desc, mutate, code] of cases) {
    it(`负例：${desc} -> ${code}`, () => {
      const tpl = typeof mutate === "object" && mutate !== null && !Array.isArray(mutate)
        ? { ...validBase, ...mutate }
        : mutate;
      const result = validateTeamTemplate(tpl);
      expect(codes(result)).toContain(code);
    });
  }

  it("gate on 合法格式放行（stage-enter 前缀约定）", () => {
    const ok = validateTeamTemplate({
      ...validBase,
      gates: [{ id: "g", at: "master", on: "stage-enter:queued" }],
    });
    expect(ok.errors.map((e) => e.code)).not.toContain("gate-on-invalid");
  });

  it("resource 计数为零也拒绝（正整数约束）", () => {
    const r = validateTeamTemplate({
      ...validBase,
      resources: { task_max_rounds: 0 },
    });
    expect(r.errors.map((e) => e.code)).toContain("resource-invalid");
  });

  it("stages_ext 含保留态即拒并给出冲突值", () => {
    const r = validateTeamTemplate({
      ...validBase,
      stages_ext: ["done"],
    });
    expect(r.errors).toContainEqual({
      code: "stage-reserved",
      path: "stages_ext",
      message: "stage conflicts with reserved: done",
    });
  });
});

tests/plugin/handlers-matrix.test.ts.source:
/**
 * team_* handler 参数校验穷举矩阵：对每个 handler 的每个必填键，
 * 断言缺失时的稳定错误码与精确消息文本；可选字段的类型违规逐一覆盖。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHandlers, type Handlers } from "../../src/plugin/handlers.js";

let home: string;
let h: Handlers;
beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-hm-"));
  h = createHandlers(home, "session-hm");
});

/** 对每个 handler 枚举必填键：缺任一键即 invalid-arguments + 精确消息。 */
const requiredMatrix: Array<{
  handler: keyof Handlers;
  setup?: () => Promise<void>;
  all: Record<string, string>; // 全部合法最小参数（值任意占位）
  stringRequired: string[];
  numberRequired?: string[];
}> = [
  {
    handler: "spawn",
    all: { member: "m", durable_id: "d", role: "r", tier: 1 },
    stringRequired: ["member", "durable_id", "role"],
    numberRequired: ["tier"],
  },
  {
    handler: "send",
    all: { to: "qa", from: "master", type: "info", body: null },
    stringRequired: ["to", "from", "type"],
    setup: async () => {},
  },
  { handler: "inbox", all: { member: "coder" }, stringRequired: ["member"] },
  { handler: "ack", all: { member: "coder", envelope_id: "e1" }, stringRequired: ["member", "envelope_id"] },
  { handler: "taskCreate", all: { title: "t", room: "root" }, stringRequired: ["title", "room"] },
  { handler: "taskUpdate", all: { task_id: "t1" }, stringRequired: ["task_id"] },
  { handler: "stateGet", all: { room: "root" }, stringRequired: ["room"] },
  { handler: "stateSet", all: { room: "root", role: "a", status: "running" }, stringRequired: ["room", "role", "status"] },
  { handler: "handoff", all: { task_id: "t1", to_role: "qa" }, stringRequired: ["task_id", "to_role"] },
];

describe("必填参数缺失矩阵", () => {
  for (const entry of requiredMatrix) {
    for (const key of entry.stringRequired) {
      it(`${String(entry.handler)}: 缺 ${key}`, async () => {
        if (entry.setup) await entry.setup();
        const args = { ...entry.all };
        delete args[key];
        await expect((h[entry.handler] as (a: object) => Promise<unknown>)(args)).rejects.toMatchObject({
          code: "invalid-arguments",
          message: `string field "${key}" is required`,
        });
      });
    }
    for (const key of entry.numberRequired ?? []) {
      it(`${String(entry.handler)}: 缺数值 ${key}`, async () => {
        const args = { ...entry.all };
        delete args[key];
        await expect((h[entry.handler] as (a: object) => Promise<unknown>)(args)).rejects.toMatchObject({
          code: "invalid-arguments",
          message: 'number field "tier" is required',
        });
      });
    }
  }
});

describe("可选字段类型违规矩阵", () => {
  const base = { member: "m", durable_id: "d", role: "r", tier: 1 };

  it("spawn.tier 非数字", async () => {
    await expect(h.spawn({ ...base, tier: "1" })).rejects.toMatchObject({
      code: "invalid-arguments",
      message: 'field "tier" must be a number',
    });
  });

  it("taskCreate.touched_paths 非字符串数组", async () => {
    await expect(
      h.taskCreate({ title: "t", room: "r", touched_paths: "src/a.ts" }),
    ).rejects.toMatchObject({ code: "invalid-arguments", message: 'field "touched_paths" must be a string array' });
  });

  it("taskCreate.dod 含非字符串元素", async () => {
    await expect(
      h.taskCreate({ title: "t", room: "r", dod: [1, 2] }),
    ).rejects.toMatchObject({ code: "invalid-arguments", message: 'field "dod" must be a string array' });
  });

  it("taskUpdate.rounds 非数字", async () => {
    const t = await (h.taskCreate({ title: "t", room: "r" }) as unknown as Promise<{ task_id: string }>);
    await expect(
      h.taskUpdate({ task_id: t.task_id, rounds: "many" }),
    ).rejects.toMatchObject({ code: "invalid-arguments", message: 'field "rounds" must be a number' });
  });

  it("stateSet.status 非保留态给 invalid-stage", async () => {
    await expect(h.stateSet({ room: "r", role: "a", status: "paused" })).rejects.toMatchObject({
      code: "invalid-stage",
    });
  });

  it("send.to 未注册成员给 unknown-member", async () => {
    await expect(h.send({ to: "ghost", from: "master", type: "info", body: null })).rejects.toMatchObject({
      code: "unknown-member",
      message: "recipient ghost is not registered",
    });
  });

  it("handoff 任务不存在给 task-not-found", async () => {
    await expect(h.handoff({ task_id: "nope", to_role: "qa" })).rejects.toMatchObject({
      code: "task-not-found",
      message: "task nope does not exist",
    });
  });
});

